import{_ as u,a0 as a,w as l,s as i,ao as s,I as n,x as e,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在Linux中使用awk命令 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中使用awk命令 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中使用awk命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中使用awk命令 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140729 How to use awk command in Linux","title":"如何在Linux中使用awk命令","tag":"201410","desc":""},"relativePath":"201410/20140729 How to use awk command in Linux.md","filePath":"[post].md"}'),k={name:"201410/20140729 How to use awk command in Linux.md"};function d(w,o,m,q,f,T){const t=a("Link");return l(),i("div",null,[o[18]||(o[18]=s(`<h1 id="如何在linux中使用awk命令" tabindex="-1">如何在Linux中使用awk命令 <a class="header-anchor" href="#如何在linux中使用awk命令" aria-label="Permalink to “如何在Linux中使用awk命令”">​</a></h1><p>文本處理是Unix的核心。從管道到/proc子系統，“一切都是文件”的理念貫穿於操作系統和所有基於它構造的工具。正因為如此，輕鬆地處理文本是一個期望成為Linux系統管理員甚至是資深用户的最重要的技能之一，而 awk是通用編程語言之外最強大的文本處理工具之一。</p><p>最簡單的awk的任務是從標準輸入中選擇字段；如果你對awk除了這個用途之外，從來沒了解過它的其他用途，你會發現它還是會是你身邊一個非常有用的工具。</p><p>默認情況下，awk通過空格分隔輸入。如果您想選擇輸入的第一個字段，你只需要告訴awk輸出$ 1：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $1}&#39;
</code></pre><blockquote><p>one</p></blockquote><p>（是的，大括號語法是有點古怪，但我保證這是我們這節課一直會遇到。）</p><p>你能猜出如何選擇第二，第三或第四個字段麼？是的，分別用$2，$ 3，$ 4。</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $3}&#39;
</code></pre><blockquote><p>three</p></blockquote><p>通常在文本改寫時，你需要創建一個特定的數據格式，並且它覆蓋不止一個單詞。好消息是，awk中可以很容易地打印多個字段，甚至包含靜態字符串：</p><pre><code> $ echo &#39;one two three four&#39; | awk &#39;{print $3,$1}&#39; 
</code></pre><blockquote><p>three one</p></blockquote><hr><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print &quot;foo:&quot;,$3,&quot;| bar:&quot;,$1}&#39; 
</code></pre><blockquote><p>foo: three | bar: one</p></blockquote><p>好吧，如果你的輸入不是由空格分隔怎麼辦？只需用awk中的&#39;-F&#39;標誌指定你的分隔符：</p><pre><code>$ echo &#39;one mississippi,two mississippi,three mississippi,four mississippi&#39; | awk -F , &#39;{print $4}&#39; 
</code></pre><blockquote><p>four mississippi</p></blockquote><p>偶爾間，你會發現自己正在處理字段數量不同的數據，但你只知道你想要的<em>最後</em>字段。 awk中內置的$NF變量代表<em>字段的數量</em>，這樣你就可以用它來抓取最後一個元素：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $NF}&#39; 
</code></pre><blockquote><p>four</p></blockquote><p>你也可以用$NF做簡單的數學，假如你需要倒數第二個字段：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $(NF-1)}&#39; 
</code></pre><blockquote><p>three</p></blockquote><p>甚至是中間的字段：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $((NF/2)+1)}&#39; 
</code></pre><blockquote><p>three</p></blockquote><p>而且這一切都非常有用，同樣你可以擺脱強制使用sed，cut，和grep來得到這些結果（儘管要做更多的操作）。</p><p>因此，我將最後為你介紹awk的一個特性，維持跨行狀態。</p><pre><code> $ echo -e &#39;one 1\\ntwo 2&#39; | awk &#39;{print $2}&#39; 
</code></pre><blockquote><p>1</p><p>2</p></blockquote><pre><code>$ echo -e &#39;one 1\\ntwo 2&#39; | awk &#39;{sum+=$2} END {print sum}&#39; 
</code></pre><blockquote><p>3</p></blockquote><p>（END代表的是我們在執行完每行的處理<strong>之後</strong>只處理下面的代碼塊）</p><p>這裏我使用的例子是統計web服務器請求日誌的字節大小。想像一下我們有如下這樣的日誌：</p><pre><code>$ cat requests.log 
</code></pre><blockquote><p>Jul 23 18:57:12 httpd[31950]: &quot;GET /foo/bar HTTP/1.1&quot; 200 344</p><p>Jul 23 18:57:13 httpd[31950]: &quot;GET / HTTP/1.1&quot; 200 9300</p><p>Jul 23 19:01:27 httpd[31950]: &quot;GET / HTTP/1.1&quot; 200 9300</p><p>Jul 23 19:01:55 httpd[31950]: &quot;GET /foo/baz HTTP/1.1&quot; 200 6401</p><p>Jul 23 19:02:31 httpd[31950]: &quot;GET /foo/baz?page=2 HTTP/1.1&quot; 200 6312</p></blockquote><p>我們知道最後一個字段是響應的字節大小。我們已經學習瞭如何使用$NF來抽取他們：</p><pre><code>$ &lt; requests.log awk &#39;{print $NF}&#39; 
</code></pre><blockquote><p>344</p><p>9300</p><p>9300</p><p>6401</p><p>6312</p></blockquote><p>接着我們可以將它們累加到一個變量中來收集我們的web服務其在日誌中這段時間內的響應客户端的字節數量</p><pre><code>$ &lt; requests.log awk &#39;{totalBytes+=$NF} END {print totalBytes}&#39; 
</code></pre><blockquote><p>31657</p></blockquote>`,44)),n("p",null,[o[2]||(o[2]=e("如果你正在尋找關於awk的更多資料，你可以在Amazon中花費不到15美元買到",-1)),p(t,{href:"http://www.amazon.com/gp/product/020107981X/ref=as_li_tl?ie=UTF8&camp=1789&creative=9325&creativeASIN=020107981X&linkCode=as2&tag=xmodulo-20&linkId=6NW62B2WBRBXRFJB"},{default:r(()=>[...o[0]||(o[0]=[e("原始awk手冊",-1)])]),_:1}),o[3]||(o[3]=e("的二手書。你也許還可以看看Eric Pement的",-1)),p(t,{href:"http://www.pement.org/awk/awk1line.txt"},{default:r(()=>[...o[1]||(o[1]=[e("單行awk命令收集",-1)])]),_:1}),o[4]||(o[4]=e("這本書。",-1))]),o[19]||(o[19]=n("hr",null,null,-1)),n("p",null,[o[6]||(o[6]=e("via: ",-1)),p(t,{href:"http://xmodulo.com/2014/07/use-awk-command-linux.html"},{default:r(()=>[...o[5]||(o[5]=[e("http://xmodulo.com/2014/07/use-awk-command-linux.html",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=e("作者：",-1)),p(t,{href:"http://xmodulo.com/author/james"},{default:r(()=>[...o[7]||(o[7]=[e("James Pearson",-1)])]),_:1}),o[11]||(o[11]=e(" 譯者：",-1)),p(t,{href:"https://github.com/geekpi"},{default:r(()=>[...o[8]||(o[8]=[e("geekpi",-1)])]),_:1}),o[12]||(o[12]=e(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:r(()=>[...o[9]||(o[9]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[15]||(o[15]=e("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[13]||(o[13]=[e("LCTT",-1)])]),_:1}),o[16]||(o[16]=e(" 原創翻譯，",-1)),p(t,{href:"http://linux.cn/"},{default:r(()=>[...o[14]||(o[14]=[e("Linux中國",-1)])]),_:1}),o[17]||(o[17]=e(" 榮譽推出",-1))])])}const c=u(k,[["render",d]]);export{x as __pageData,c as default};
